export interface GcpBackendOptions {
  /** Override GCS bucket name (default: same as S3 bucket). */
  readonly bucket?: string;
  /** Override prefix (default: derived from key path). */
  readonly prefix?: string;
}

// ---------------------------------------------------------------------------
// Helpers
