/**
 * Extracts the directory prefix from an S3 key path.
 * e.g. "env/prod/terraform.tfstate" -> "env/prod"
 * If no directory component, returns the key as-is.
 */
function keyToPrefix(key: string): string {
  const lastSlash = key.lastIndexOf('/');
  if (lastSlash > 0) {
    return key.substring(0, lastSlash);
  }
  return key;
}

