// Generator
// ---------------------------------------------------------------------------

/**
 * Generates a GCS backend HclMapEntry from S3 backend attributes.
 *
 * Mapping:
 * - bucket -> bucket
 * - key path directory -> prefix
 *
 * @returns An HclMapEntry with key `backend "gcs"` and a block value.
 */
export function generateGcpBackend(
  attrs: S3BackendAttributes,
  options?: GcpBackendOptions,
): HclMapEntry {
  const body: Record<string, HclValue> = {
    bucket: literal(options?.bucket ?? attrs.bucket),
    prefix: literal(options?.prefix ?? keyToPrefix(attrs.key)),
  };

  return {
    key: 'backend "gcs"',
    value: block(body),
  };
}
